#!/usr/bin/env python3
from pathlib import Path
from playwright.sync_api import sync_playwright, expect
import json

ROOT=Path(__file__).resolve().parents[1]
css='\n'.join((ROOT/p).read_text(encoding='utf-8') for p in ['assets/css/tokens.css','assets/css/app.css','assets/css/responsive.css','assets/css/panel.css','assets/css/items-management.css'])
js=(ROOT/'assets/js/items-management.js').read_text(encoding='utf-8')
order_js=(ROOT/'assets/js/reorder-list.js').read_text(encoding='utf-8')
items={
  1:{'id':1,'name':'شیک توت‌فرنگی','price':345000,'category_id':2,'category_name':'نوشیدنی سرد','preparation_station':'cold_bar','station_label':'بار سرد','available':True,'active':True,'staff_only':False,'featured':True,'schedule_summary':'همیشه در دسترس منو','schedule_now':True,'has_schedule':False},
  2:{'id':2,'name':'چای سیاه','price':125000,'category_id':1,'category_name':'نوشیدنی گرم','preparation_station':'hot_bar','station_label':'بار گرم','available':False,'active':True,'staff_only':False,'featured':False,'schedule_summary':'دوشنبه · ۰۸:۰۰ تا ۱۲:۰۰','schedule_now':False,'has_schedule':True},
}
row=lambda i:f'''<article class="item-management-row" data-item-row="{i}"><label class="item-row-select"><input data-item-select type="checkbox" value="{i}"></label><div class="item-admin-identity"><div class="item-admin-thumb"></div><div><strong data-item-name>{items[i]['name']}</strong><small>ITEM-{i}</small><span data-featured-badge class="badge {'hidden' if not items[i]['featured'] else ''}">پیشنهاد کافه</span></div></div><div class="item-admin-context"><strong data-item-category>{items[i]['category_name']}</strong><small data-item-station>{items[i]['station_label']}</small></div><div class="item-admin-commercial"><strong data-item-price>{items[i]['price']}</strong><small>{items[i]['schedule_summary']}</small></div><div class="item-admin-state"><button class="state-toggle {'is-on' if items[i]['available'] else 'is-off'}" data-item-action="availability" data-item-id="{i}"><span></span><b>{'قابل سفارش' if items[i]['available'] else 'غیرقابل سفارش'}</b></button><button class="state-toggle is-on" data-item-action="active" data-item-id="{i}"><span></span><b>در منو</b></button></div><div class="item-admin-actions"><button class="btn" data-quick-edit-item="{i}">ویرایش سریع</button></div></article>'''
html=f'''<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>:root{{--primary:#365b4c;--accent:#b85c38;--line:#e5ddd3;--muted:#736b64;--danger:#a33;--success:#16845b}}{css}</style></head><body class="panel-body panel-section-items"><div id="panelToast" class="hidden"></div><main class="panel-content"><section class="items-overview"><div class="items-overview-copy"><h2>آیتم‌های منو</h2></div><div class="items-overview-stats"><span><small>کل</small><strong>۲</strong></span><span><small>غیرقابل سفارش</small><strong>۱</strong></span><span><small>پیش‌نویس</small><strong>۰</strong></span></div></section><form class="item-filter-bar" id="itemFilterForm"><label><span>جست‌وجو</span><input class="form-control"></label><label><span>دسته</span><select><option>همه</option></select></label><label><span>وضعیت</span><select><option>همه</option></select></label><label><span>بخش</span><select><option>همه</option></select></label><div class="item-filter-actions"><button>نمایش</button></div></form><div class="item-selection-bar hidden" id="itemSelectionBar"><strong><span id="selectedItemCount">۰</span> آیتم</strong><select id="bulkItemOperation"><option value="">انتخاب</option><option value="category">دسته</option></select><select id="bulkCategoryTarget" class="hidden"><option value="2">سرد</option></select><select id="bulkStationTarget" class="hidden"></select><button id="applyBulkItemAction"></button><button id="clearItemSelection"></button></div><section class="card items-management-card"><div class="items-list-head"><span><input id="selectAllItems" type="checkbox"></span><span>آیتم</span><span>دسته</span><span>قیمت</span><span>وضعیت</span><span>عملیات</span></div><div class="items-management-list">{row(1)}{row(2)}</div></section></main><div class="item-editor-backdrop hidden" id="itemEditorBackdrop"></div><aside class="item-editor-drawer hidden" id="itemEditorDrawer"><form id="itemQuickEditForm"><header><h2 id="itemEditorTitle"></h2><button type="button" data-close-item-editor>×</button></header><div class="item-editor-body"><input id="quickItemId"><input id="quickItemName" name="name"><input id="quickItemPrice" name="price"><select id="quickItemCategory"><option value="1">گرم</option><option value="2">سرد</option></select><select id="quickItemStation"><option value="hot_bar">بار گرم</option><option value="cold_bar">بار سرد</option></select><input type="checkbox" id="quickItemAvailable"><input type="checkbox" id="quickItemActive"><input type="checkbox" id="quickItemStaffOnly"><input type="checkbox" id="quickItemTakeaway"><input type="checkbox" id="quickItemFeatured"><div id="quickItemScheduleWrap"><p id="quickItemSchedule"></p></div></div><footer><a id="quickItemFullEdit"></a><button type="submit">ذخیره</button></footer></form></aside><script>window.SOKNA_ITEMS={json.dumps(items,ensure_ascii=False)};window.SOKNA_ITEMS_ENDPOINT='/items';window.SOKNA_ITEMS_CSRF='x';window.SOKNA_ITEMS_FILTERED=false;window.CafeUI={{toast:(m,t)=>window.__toast=m,confirm:async()=>true}};window.fetch=async(u,o)=>{{const p=JSON.parse(o.body);let item=window.SOKNA_ITEMS[p.id];if(p.action==='availability')item={{...item,available:Boolean(Number(p.desired_state))}};if(p.action==='active')item={{...item,active:Boolean(Number(p.desired_state))}};if(p.action==='quick_update')item={{...item,name:p.name,price:Number(p.price),category_id:p.category_id,category_name:p.category_id===1?'نوشیدنی گرم':'نوشیدنی سرد',preparation_station:p.preparation_station,station_label:p.preparation_station==='hot_bar'?'بار گرم':'بار سرد',available:p.available,active:p.active,staff_only:p.staff_only,featured:p.featured}};window.SOKNA_ITEMS[p.id]=item;return new Response(JSON.stringify({{success:true,message:'ذخیره شد',item}}),{{status:200,headers:{{'Content-Type':'application/json'}}}})}};</script><script>{js}</script></body></html>'''
order_html=f'''<!doctype html><html lang="fa" dir="rtl"><head><style>{css}</style></head><body><form data-reorder-form><input id="orderedItemIds" data-reorder-output><section data-reorder-list class="reorder-list"><article class="reorder-row" draggable="true" data-reorder-id="1"><button data-reorder-handle type="button"></button><b>یک</b><div><button type="button" data-reorder-up>بالا</button><button type="button" data-reorder-down>پایین</button></div></article><article class="reorder-row" draggable="true" data-reorder-id="2"><button data-reorder-handle type="button"></button><b>دو</b><div><button type="button" data-reorder-up>بالا</button><button type="button" data-reorder-down>پایین</button></div></article></section></form><script>{order_js}</script></body></html>'''

with sync_playwright() as p:
    browser=p.chromium.launch(headless=True,executable_path='/usr/bin/chromium',args=['--no-sandbox'])
    for width in (390,1024,1440):
        page=browser.new_page(viewport={'width':width,'height':900})
        page.set_content(html,wait_until='load')
        assert page.evaluate('document.documentElement.scrollWidth <= innerWidth + 1'), width
        page.locator('[data-quick-edit-item="1"]').click()
        assert page.locator('#itemEditorDrawer').is_visible()
        page.locator('#quickItemName').fill('شیک ویژه توت‌فرنگی')
        page.locator('#quickItemPrice').fill('360000')
        page.locator('#itemQuickEditForm').evaluate('(f)=>f.requestSubmit()')
        expect(page.locator('#itemEditorDrawer')).to_be_hidden(timeout=3000)
        expect(page.locator('[data-item-row="1"] [data-item-name]')).to_have_text('شیک ویژه توت‌فرنگی', timeout=3000)
        page.locator('[data-item-row="1"] [data-item-action="availability"]').click()
        expect(page.locator('[data-item-row="1"] [data-item-action="availability"] b')).to_have_text('غیرقابل سفارش', timeout=3000)
        page.locator('[data-item-select]').nth(0).check(); page.locator('[data-item-select]').nth(1).check()
        assert page.locator('#itemSelectionBar').is_visible()
        assert page.locator('#selectedItemCount').inner_text()=='۲'
        page.locator('#bulkItemOperation').select_option('category')
        assert page.locator('#bulkCategoryTarget').is_visible()
        page.close()
    order=browser.new_page(viewport={'width':390,'height':700});order.set_content(order_html)
    order.locator('[data-reorder-id="2"] [data-reorder-up]').click()
    assert order.locator('[data-reorder-id]').first.get_attribute('data-reorder-id')=='2'
    assert json.loads(order.locator('#orderedItemIds').input_value())==[2,1]
    browser.close()
print('Item management browser checks passed: responsive list, quick edit, direct states, bulk selection and menu ordering.')
